import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const UserDashboard = ({ onAdminClick }) => {
  const [slots, setSlots] = useState([]);

  useEffect(() => {
    fetchSlots();
    const interval = setInterval(fetchSlots, 2000); // live update every 2s
    return () => clearInterval(interval);
  }, []);

  async function fetchSlots() {
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("slot", { ascending: true });

    if (error) console.log("Error fetching slots:", error);
    else setSlots(data);
  }

  const totalSlots = slots.length;
  const occupied = slots.filter(s => s.status === "occupied").length;
  const vacant = totalSlots - occupied;

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
      {/* Top Bar */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
        <h1>🏬 MyMall Smart Parking</h1>
        <button 
          onClick={onAdminClick} 
          style={{
            padding: "8px 16px",
            backgroundColor: "#007bff",
            color: "#fff",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer"
          }}
        >
          Admin Login
        </button>
      </div>

      {/* Summary Cards */}
      <div style={{ display: "flex", gap: "20px", marginBottom: "30px" }}>
        <div style={{ flex: 1, background: "#f5f5f5", padding: "20px", borderRadius: "8px", textAlign: "center" }}>
          <h3>Total Slots</h3>
          <p style={{ fontSize: "24px", fontWeight: "bold" }}>{totalSlots}</p>
        </div>
        <div style={{ flex: 1, background: "#d4edda", padding: "20px", borderRadius: "8px", textAlign: "center" }}>
          <h3>Available Slots</h3>
          <p style={{ fontSize: "24px", fontWeight: "bold" }}>{vacant}</p>
        </div>
        <div style={{ flex: 1, background: "#f8d7da", padding: "20px", borderRadius: "8px", textAlign: "center" }}>
          <h3>Occupied Slots</h3>
          <p style={{ fontSize: "24px", fontWeight: "bold" }}>{occupied}</p>
        </div>
      </div>

      {/* Slot List */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "20px" }}>
        {slots.map(slot => {
          const lastActivity = slot.time 
            ? `${Math.floor((new Date() - new Date(slot.time)) / 60000)}m ago`
            : "—";

          return (
            <SlotCard 
              key={slot.id} 
              slot={{
                ...slot,
                lastActivity
              }} 
            />
          );
        })}
      </div>
    </div>
  );
};

export default UserDashboard;
